// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.str;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import org.junit.jupiter.api.Test;

/**
 * {@code dtf:parseDate(s, pattern [, locale])} resolves the parsed fields strictly: a calendar date or clock time that
 * does not exist is a SPARQL evaluation error instead of being clamped to the nearest valid value.
 */
class ParseDateStrictResolutionTest {

	private final ParseDate parseDate = new ParseDate();

	@Test
	void nonExistentCalendarDatesAreAnEvaluationError() {
		assertEvaluationError("30 February 2024",
				() -> parseDate.evaluate(VF, str("2024-02-30"), str("yyyy-MM-dd")));
		assertEvaluationError("29 February 2023 (not a leap year)",
				() -> parseDate.evaluate(VF, str("2023-02-29"), str("yyyy-MM-dd")));
		assertEvaluationError("31 April 2024",
				() -> parseDate.evaluate(VF, str("31/04/2024"), str("dd/MM/yyyy")));
		assertEvaluationError("30 February with a time",
				() -> parseDate.evaluate(VF, str("2024-02-30 10:11"), str("yyyy-MM-dd HH:mm")));
	}

	@Test
	void midnightAsHourTwentyFourIsAnEvaluationError() {
		assertEvaluationError("24:00", () -> parseDate.evaluate(VF, str("24:00"), str("HH:mm")));
		assertEvaluationError("24:00:00", () -> parseDate.evaluate(VF, str("24:00:00"), str("HH:mm:ss")));
		assertEvaluationError("date with 24:00",
				() -> parseDate.evaluate(VF, str("2024-05-17 24:00"), str("yyyy-MM-dd HH:mm")));
	}

	@Test
	void outOfRangeFieldsStayAnEvaluationError() {
		assertEvaluationError("day 32", () -> parseDate.evaluate(VF, str("2024-02-32"), str("yyyy-MM-dd")));
		assertEvaluationError("month 13", () -> parseDate.evaluate(VF, str("2024-13-01"), str("yyyy-MM-dd")));
		assertEvaluationError("month 0", () -> parseDate.evaluate(VF, str("2024-00-10"), str("yyyy-MM-dd")));
		assertEvaluationError("day 0", () -> parseDate.evaluate(VF, str("2024-05-00"), str("yyyy-MM-dd")));
		assertEvaluationError("minute 60", () -> parseDate.evaluate(VF, str("10:60"), str("HH:mm")));
		assertEvaluationError("hour 25", () -> parseDate.evaluate(VF, str("25:00"), str("HH:mm")));
		assertEvaluationError("second 60", () -> parseDate.evaluate(VF, str("10:11:60"), str("HH:mm:ss")));
	}

	@Test
	void validDatesWithYearOfEraPatternsStillParse() {
		// yyyy is year-of-era, which java.time's strict resolver refuses without an era; parseDate must keep
		// accepting it the way it always has
		assertThat(parseDate.evaluate(VF, str("17/05/2024"), str("dd/MM/yyyy"))).isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("2024-02-29"), str("yyyy-MM-dd"))).isEqualTo(date("2024-02-29"));
		assertThat(parseDate.evaluate(VF, str("2024-12-31"), str("yyyy-MM-dd"))).isEqualTo(date("2024-12-31"));
		assertThat(parseDate.evaluate(VF, str("2024-01-01"), str("yyyy-MM-dd"))).isEqualTo(date("2024-01-01"));
		assertThat(parseDate.evaluate(VF, str("17.05.24"), str("dd.MM.yy"))).isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("17.05.2024 10:11"), str("dd.MM.yyyy HH:mm")))
				.isEqualTo(dt("2024-05-17T10:11:00"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17T10:11:12"), str("yyyy-MM-dd'T'HH:mm:ss")))
				.isEqualTo(dt("2024-05-17T10:11:12"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17 10:11:12.123456789"), str("yyyy-MM-dd HH:mm:ss.SSSSSSSSS")))
				.isEqualTo(dt("2024-05-17T10:11:12.123456789"));
		// a proleptic-year pattern keeps working as well
		assertThat(parseDate.evaluate(VF, str("2024-05-17"), str("uuuu-MM-dd"))).isEqualTo(date("2024-05-17"));
	}

	@Test
	void quotedLiteralTextIsNotRewritten() {
		// the y and G letters inside quotes are literal text, not year-of-era or era fields
		assertThat(parseDate.evaluate(VF, str("day 17.05.2024"), str("'day' dd.MM.yyyy")))
				.isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("Generated 2024-05-17"), str("'Generated' yyyy-MM-dd")))
				.isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("year 2024 o'clock 05 17"), str("'year' yyyy 'o''clock' MM dd")))
				.isEqualTo(date("2024-05-17"));
		assertEvaluationError("quoted text with a clamped date",
				() -> parseDate.evaluate(VF, str("day 30.02.2024"), str("'day' dd.MM.yyyy")));
	}

	@Test
	void yearOfEraWithAnEraFieldParses() {
		assertThat(parseDate.evaluate(VF, str("2024-05-17 AD"), str("yyyy-MM-dd G"), str("en")))
				.isEqualTo(date("2024-05-17"));
		assertEvaluationError("era with a clamped date",
				() -> parseDate.evaluate(VF, str("2024-02-30 AD"), str("yyyy-MM-dd G"), str("en")));
	}

	@Test
	void monthNamesWithALocaleParse() {
		assertThat(parseDate.evaluate(VF, str("17 mai 2024"), str("d MMMM yyyy"), str("fr")))
				.isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("17 May 2024"), str("d MMM yyyy"), str("en")))
				.isEqualTo(date("2024-05-17"));
		assertThat(parseDate.evaluate(VF, str("Freitag 17 Mai 2024"), str("EEEE d MMMM yyyy"), str("de")))
				.isEqualTo(date("2024-05-17"));
		assertEvaluationError("30 February with a month name",
				() -> parseDate.evaluate(VF, str("30 February 2024"), str("d MMMM yyyy"), str("en")));
	}

	@Test
	void zonesAndOffsetsParse() {
		assertThat(parseDate.evaluate(VF, str("2024-05-17 10:11 +0200"), str("yyyy-MM-dd HH:mm Z")))
				.isEqualTo(dt("2024-05-17T10:11:00+02:00"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17 10:11:12+05:30"), str("yyyy-MM-dd HH:mm:ssXXX")))
				.isEqualTo(dt("2024-05-17T10:11:12+05:30"));
		assertThat(parseDate.evaluate(VF, str("2024-05-17+02:00"), str("yyyy-MM-ddXXX")))
				.isEqualTo(date("2024-05-17+02:00"));
		assertThat(parseDate.evaluate(VF, str("2024-06-01 12:00 Europe/Oslo"), str("yyyy-MM-dd HH:mm VV")))
				.isEqualTo(dt("2024-06-01T12:00:00+02:00"));
		assertThat(parseDate.evaluate(VF, str("2024-01-01 12:00 UTC"), str("yyyy-MM-dd HH:mm z"), str("en")))
				.isEqualTo(dt("2024-01-01T12:00:00Z"));
		assertEvaluationError("30 February with an offset",
				() -> parseDate.evaluate(VF, str("2024-02-30 10:11:12+05:30"), str("yyyy-MM-dd HH:mm:ssXXX")));
	}

	@Test
	void timeOnlyPatternsParse() {
		assertThat(parseDate.evaluate(VF, str("10:11"), str("HH:mm"))).isEqualTo(time("10:11:00"));
		assertThat(parseDate.evaluate(VF, str("00:00"), str("HH:mm"))).isEqualTo(time("00:00:00"));
		assertThat(parseDate.evaluate(VF, str("23:59:59"), str("HH:mm:ss"))).isEqualTo(time("23:59:59"));
		assertThat(parseDate.evaluate(VF, str("10:11:12.5"), str("HH:mm:ss.S"))).isEqualTo(time("10:11:12.5"));
		assertThat(parseDate.evaluate(VF, str("10:11Z"), str("HH:mmXXX"))).isEqualTo(time("10:11:00Z"));
	}
}
